@startuml

enum RequestType {
  SOBER_APP
  HAND_WAVING
}

class Car {
  + vehicleNumber : string
}

class Owner {
  + name : string
}

class Accident {
  + date : date
  + location : string
  + damageAmount : double
}

class Customer {
  + name : string
}

class RideHail {
  + pickUpTime : time
  + dropOffTime : time
  + pickUpLocation : string
  + dropOffLocation : string
  + rideDuration : string
  + distance : double
  + numberOfPassengers : int
  + fee : double
  + requestType : RequestType
}

class RideShare {
  + pickUpTime : time
  + dropOffTime : time
  + pickUpLocation : string
  + dropOffLocation : string
  + rideDuration : string
  + distance : double
  + numberOfPassengers : int
  + upfrontNegotiatedFee : double
}

Car "1" -- "0..*" Accident : experiences
Car "0..1" -- "0..*" Owner : owned by
Car "1" -- "0..*" RideHail : provides
Car "1" -- "0..*" RideShare : provides
RideHail "0..*" -- "1" Customer : lead customer
RideShare "*" -- "1..10" Customer : passengers

@enduml

